// Nested (hard to update)
{
  users: [
    { id: 1, name: 'Alice', posts: [{ id: 1, title: 'Hello' }] }
  ]
}

// Normalized (easy to update)
{
  users: {
    byId: { 1: { id: 1, name: 'Alice', posts: [1] } },
    allIds: [1]
  },
  posts: {
    byId: { 1: { id: 1, title: 'Hello', author: 1 } },
    allIds: [1]
  }
}
